mapper.select:
SELECT id, source_event_id, tenant_id, recipient_user_id, notification_type,
       title, content, status, created_at, read_at
FROM notifications
WHERE tenant_id = #{tenantId}
  AND recipient_user_id = #{recipientUserId, jdbcType=OTHER}
ORDER BY created_at DESC
LIMIT #{limit}

mapper.update:
UPDATE notifications
SET status = 'READ',
    read_at = COALESCE(read_at, #{readAt})
WHERE id = #{notificationId, jdbcType=OTHER}
  AND tenant_id = #{tenantId}
  AND recipient_user_id = #{recipientUserId, jdbcType=OTHER}
